import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { uv, mix, vec3, mul, add, sin, dot, fract, float, vec2, scale } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color } = ctx.THREE;

  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeo = new PlaneGeometry(7, 5.5);
  const gradientStops = (config.colors?.gradientStops) || [];
  const startColor = new Color(gradientStops[0]?.hex ?? '#0b0b10');
  const endColor = new Color(gradientStops[1]?.hex ?? '#14141a');

  // Gradient node
  const gradNode = mix(
    vec3(startColor),
    vec3(endColor),
    uv().y
  );

  // Grain (≈1.5%)
  const grainNoise = mul(
    fract(sin(dot(mul(uv(), float(100)), vec2(12.9898, 78.233))) * 43758.5453),
    float(0.015)
  );
  const finalColor = add(gradNode, grainNoise);

  const backdropMat = new MeshBasicNodeMaterial({ color: finalColor });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5; // back plane as per spec (z=-2.5)
  root.add(backdrop);

  // ---------- TEXT ----------
  const leftX = -3.1;
  const textItems = [
    {
      role: 'kicker',
      text: 'NOVA ATELIER / JOURNAL',
      y: 1.7,
      fontSize: 18,
      fontWeight: 700,
      tracking: 0.12,
      color: config.colors?.ink ?? '#16161d',
      family: 'JetBrains Mono'
    },
    {
      role: 'hero1',
      text: 'PRECISION IS',
      y: 0.9,
      fontSize: 124,
      fontWeight: 600,
      tracking: -0.015,
      color: config.colors?.ink ?? '#16161d',
      family: 'Lora'
    },
    {
      role: 'hero2',
      text: 'A HABIT.',
      y: 0.25,
      fontSize: 124,
      fontWeight: 600,
      tracking: -0.015,
      color: config.colors?.ink ?? '#16161d',
      family: 'Lora'
    },
    {
      role: 'body',
      text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
      y: -0.8,
      fontSize: 26,
      fontWeight: 400,
      tracking: 0,
      maxWidthPx: 4500, // rough conversion (scene units * 1000)
      color: config.colors?.paper ?? '#e8ecf2',
      family: 'JetBrains Mono'
    },
    {
      role: 'caption',
      text: 'ISSUE 12 / JULY 2026',
      y: -1.9,
      fontSize: 18,
      fontWeight: 400,
      tracking: 0.08,
      color: config.colors?.paper ?? '#e8ecf2',
      family: 'JetBrains Mono'
    }
  ];

  const blocks = [];

  textItems.forEach(item => {
    // Main text
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.fontSize,
      color: item.color,
      align: 'left',
      letterSpacingPx: item.tracking * item.fontSize
    });
    txt.position.set(leftX, item.y, 0);
    root.add(txt);
    blocks.push(txt);

    // Hero shadow duplication (only for hero lines)
    if (item.role.startsWith('hero')) {
      const shadow = ctx.fontAtlas.createText(item.text, {
        fontSize: item.fontSize,
        color: config.colors?.ink ?? '#16161d',
        align: 'left',
        letterSpacingPx: item.tracking * item.fontSize
      });
      shadow.position.set(leftX, item.y, -0.02);
      root.add(shadow);
    }
  });

  // ---------- UNDERLINE ----------
  const underlineGeo = new PlaneGeometry(2.2, 0.05);
  const underlineMat = new MeshStandardNodeMaterial({
    color: new Color(config.colors?.accent ?? '#ff2a38'),
    emissive: new Color(config.colors?.accent ?? '#ff2a38'),
    emissiveIntensity: 1.2,
    transparent: true,
    side: 2 // DoubleSide
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(leftX + 2.2 / 2, -0.15, 0);
  underline.scale.x = 0;
  root.add(underline);

  // ---------- ANIMATION ----------
  const master = gsap.timeline({ defaults: { ease: 'power3.out' } });
  const stagger = 0.08;

  blocks.forEach((blk, idx) => {
    // ensure transparency
    blk.traverse(child => {
      if (child.isMesh) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
    // start offset
    blk.position.y += 0.4;
    master.from(blk.position, { y: '-=0.4', duration: 0.7 }, idx * stagger);
    master.from(
      blk.children.map(c => c.material),
      { opacity: 0, duration: 0.7 },
      idx * stagger
    );
    // After hero2 (idx 2) add underline animation
    if (idx === 2) {
      master.add(
        gsap.to(underline.scale, {
          x: 1,
          duration: 0.5,
          ease: 'power2.out'
        }),
        '+=0.1'
      );
    }
  });

  // ---------- CLEANUP ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    master.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    blocks.forEach(blk => {
      blk.traverse(child => {
        if (child.isMesh) {
          child.geometry?.dispose();
          child.material?.dispose();
        }
      });
    });
  };

  return root;
}
